import pandas as pd

def find_trending_hashtags_ii(tweets: pd.DataFrame) -> pd.DataFrame:
    df = tweets.copy()
    df['tweet_date'] = pd.to_datetime(df['tweet_date'])
    df = df[(df['tweet_date'] >= '2024-02-01') & (df['tweet_date'] <= '2024-02-29')]
    if df.empty:
        return pd.DataFrame(columns=['hashtag', 'count'])

    tags = df['tweet'].str.findall(r'(#[^\s]+)').explode().dropna()
    if tags.empty:
        return pd.DataFrame(columns=['hashtag', 'count'])

    res = tags.value_counts().reset_index()
    res.columns = ['hashtag', 'count']
    return res.sort_values(by=['count', 'hashtag'], ascending=[False, False]).head(3)
